-- Add the third supplied set of Lily facts (cards 201–300). This is
-- append-only: existing fact cards and their learner delivery history stay intact.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (201, $$Роберт Хейнлайн в романе «Никакой проку от рекламы» (1947 год) детально описал идею использования водяных матрасов. Патентное ведомство США позже отказало реальному изобретателю в патенте, сославшись на то, что Хейнлайн уже описал устройство.$$),
  (202, $$Эдгар Аллан По в «Повести о приключениях Артура Гордона Пима» (1838) описал кораблекрушение, при котором трое выживших матросов съели четвертого — юнгу по имени Ричард Паркер. Через 46 лет в реальности затонула яхта «Mignonette», и трое выживших матросов съели своего юнгу, которого действительно звали Ричард Паркер.$$),
  (203, $$Джонатан Свифт в «Путешествиях Гулливера» (1726) не просто указал наличие двух лун у Марса, но и с поразительной точностью описал их орбиты и периоды обращения. Астрономы открыли их только в 1877 году.$$),
  (204, $$Марк Твен родился в 1835 году, в день, когда рядом с Землей пролетала комета Галлея. Писатель предсказал, что умрет, когда она вернется. Так и случилось: Твен скончался от сердечного приступа в 1910 году, на следующий день после очередного перигелия кометы.$$),
  (205, $$Том Клэнси в романе «Долг чести» (1994) описал террориста, который направляет угнанный коммерческий Boeing 747 прямо в здание Капитолия в Вашингтоне. Спустя 7 лет произошла трагедия 11 сентября.$$),
  (206, $$Александр Беляев в романе «Голова профессора Доуэля» (1925) описал трансплантацию органов и поддержание жизни в отделенной от тела голове. Писатель создавал книгу, будучи сам годами прикованным к постели из-за костного туберкулеза, и буквально «чувствовал себя головой без тела».$$),
  (207, $$Хорхе Луис Борхес в рассказе «Вавилонская библиотека» (1941) описал бесконечную библиотеку, содержащую все возможные комбинации букв. В XXI веке программисты реализовали этот концепт в виде сайта libraryofbabel.info, где сгенерированы абсолютно все тексты, которые когда-либо были или будут написаны.$$),
  (208, $$Карел Чапек в романе «Кракатит» (1922) описал вещество, способное вызывать взрывы колоссальной силы за счет расщепления атомов. Это произошло за 23 года до Хиросимы.$$),
  (209, $$Джон Толкин описал в «Властелине колец» Око Саурона — гигантский пылающий глаз. Спустя полвека астрономы обнаружили в созвездии Водолея планетарную туманность Улитка, которая на снимках телескопов выглядит один в один как глаз Саурона.$$),
  (210, $$Фантаст Джон Браннер в романе «Всем стоять на Занзибаре» (1968 год) предсказал для 2010 года: появление Евросоюза, спутникового радио, видеотелефонов, лазерных принтеров, а также то, что главным геополитическим соперником США станет Китай, а не СССР.$$),
  (211, $$Уильям Берроуз (автор «Голого завтрака») во время пьяной вечеринки решил сыграть с женой в «Вильгельма Телля». Он поставил ей на голову стакан и попытался сбить его выстрелом из пистолета, но промахнулся и убил супругу. Его признали виновным в непредумышленном убийстве и дали условный срок.$$),
  (212, $$О. Генри (Уильям Сидней Портер) начал писать свои знаменитые юмористические рассказы, находясь в тюрьме, где он отбывал трехлетний срок за растрату банковских средств. Там же он и придумал свой псевдоним.$$),
  (213, $$Анн и Серж Голон (авторы романов об Анжелике) писали свои книги в условиях жесткой конспирации. Серж (Всеволод Голубинов) в юности был русским эмигрантом, ученым-химиком и геологом, бежавшим от революции, и долгое время скрывался от советских спецслужб.$$),
  (214, $$Томас Мэлори написал великий рыцарский роман «Смерть Артура», сидя в тюрьме. Причем сидел он не за политику, а за реальный разбой, кражу скота, вымогательство и нападения на замки.$$),
  (215, $$Дэниел Дефо был не просто писателем, а профессиональным тайным агентом и шпионом британской короны. Он стоял у истоков создания британской секретной службы MI6.$$),
  (216, $$Франсуа Вийон, величайший поэт французского Средневековья, был профессиональным вором, состоял в банде кокильяров, грабил церкви и несколько раз приговаривался к смертной казни через повешение, но каждый раз получал помилование.$$),
  (217, $$Чарльз Буковски почти 10 лет проработал обычным почтальоном и сортировщиком писем. Он уволился и стал профессиональным писателем только в 49 лет, когда издатель предложил ему пожизненную выплату в 100 долларов в месяц.$$),
  (218, $$Кен Кизи написал «Пролетая над гнездом кукушки», работая ночным санитаром в психиатрической больнице. Более того, он добровольно участвовал в секретных правительственных экспериментах проекта МК-Ультра, тестируя на себе ЛСД и другие психоделики.$$),
  (219, $$Донасьен Альфонс Франсуа де Сад (Маркиз де Сад) провел в тюрьмах и психбольницах в общей сложности 27 лет своей жизни. Именно там он написал большинство своих скандальных рукописей на длинных рулонах бумаги, скрывая их от тюремщиков.$$),
  (220, $$Артур Конан Дойл лично расследовал два реальных уголовных дела. Используя методы своего же Шерлока Холмса, он доказал невиновность Джорджа Эдалджи (которого обвиняли в калечении скота) и Оскара Слейтера (обвиненного в убийстве).$$),
  (221, $$Фридрих Шиллер мог писать свои драмы только тогда, когда в ящике его рабочего стола лежали гнилые яблоки. Их резкий запах, по словам поэта, стимулировал его вдохновение.$$),
  (222, $$Шарлотта Бронте во время написания романов постоянно прерывала работу, чтобы почистить картофель. Это помогало ей отвлечься и обдумать следующую сцену.$$),
  (223, $$Александр Пушкин обожал стрелять в бане. В своем имении Михайловское он часами тренировался в меткости, расстреливая стену из пистолета, чтобы рука на реальной дуэли не дрогнула.$$),
  (224, $$Вирджиния Вулф, как и Хемингуэй, писала свои романы исключительно стоя за специальным высоким столом, считая, что сидячее положение «убивает динамику мысли».$$),
  (225, $$Жан-Жак Руссо утверждал, что его мозг работает продуктивно только тогда, когда его голова находится под прямыми лучами палящего солнца. Поэтому он часто гулял в полдень без головного убора.$$),
  (226, $$Льюис Кэрролл вел подробнейшие журналы всей своей переписки. За 37 лет он зарегистрировал и пронумеровал 98 721 письмо.$$),
  (227, $$Эмиль Золя во время работы привязывал себя веревкой к стулу, чтобы преодолеть лень и не иметь возможности встать и уйти из кабинета до тех пор, пока не напишет дневную норму страниц.$$),
  (228, $$Альфред Хичкок (хоть он и режиссер, но написал несколько сборников детективных рассказов) панически боялся предметов овальной формы, особенно обычных куриных яиц. Он утверждал, что никогда в жизни не пробовал яйца.$$),
  (229, $$Михаил Лермонтов был крайне неразборчив в еде и часто не замечал, что ест. Друзья однажды подшутили над ним, подложив в булочки опилки. Поэт съел их и ничего не заметил, после чего сильно обиделся на шутников.$$),
  (230, $$Джеймс Джойс праздновал день рождения исключительно в день выхода своей новой книги. Если издатели не успевали напечатать тираж к его дате, он впадал в ярость и устраивал скандалы.$$),
  (231, $$Комикс «Экшн Комикс №1» (1938 год), в котором впервые появился Супермен, изначально продавался по цене 10 центов. Сегодня уцелевшие экземпляры продаются на аукционах более чем за 3–5 миллионов долларов.$$),
  (232, $$Роберт Ладлэм (автор трилогии о Джейсоне Борне) перед публикацией первой книги провел исследование и выяснил, что в названиях бестселлеров чаще всего присутствуют три слова. С тех пор почти все его книги назывались по схеме: «Идентификация Борна», «Превосходство Борна» и т.д.$$),
  (233, $$Серия романов «Гарри Поттер» — самая продаваемая серия книг в истории человечества. Общий тираж превышает 600 миллионов экземпляров на 85 языках.$$),
  (234, $$Первой аудиокнигой в мире стала запись поэмы Эдгара По «Ворон», сделанная на восковой цилиндр Томасом Эдисоном в его лаборатории.$$),
  (235, $$Стивен Кинг попал в Книгу рекордов Гиннесса как автор, у которого самое большое количество книг адаптировано для кино и телевидения при жизни.$$),
  (236, $$«Маленький принц» — самая читаемая книга в мире после религиозных текстов. Существуют издания даже на исчезающих языках североамериканских индейцев и на азбуке Брайля для слепых.$$),
  (237, $$Термин «Бестселлер» впервые был использован в газете The Kansas City Star в 1889 году в статье о книжных новинках.$$),
  (238, $$Самый большой гонорар в истории поэзии получил Александр Пушкин за поэму «Бахчисарайский фонтан» — 3 000 рублей (огромное состояние по меркам 1824 года, эквивалентное годовому доходу крупного чиновника).$$),
  (239, $$Издательство Penguin Books в 1935 году произвело революцию в мире чтения, начав выпускать качественную художественную литературу в мягкой обложке по цене одной пачки сигарет. Это сделало чтение доступным для бедных слоев населения.$$),
  (240, $$Барбара Картленд внесена в Книгу рекордов Гиннесса как самый продуктивный британский автор: она написала 723 любовных романа, причем в некоторые периоды выпускала по две книги в месяц, просто надиктовывая их стенографисткам.$$),
  (241, $$Роман Чарльза Диккенса «Оливер Твист» настолько шокировал британское общество описанием жестокости в работных домах, что правительство Великобритании было вынуждено пересмотреть «Закон о бедных» и провести масштабную реформу детских приютов.$$),
  (242, $$«Джунгли» Эптона Синклера (1906) — роман, описывающий ужасающую антисанитарию на мясных бойнях Чикаго. Президент Теодор Рузвельт прочитал книгу, назначил проверку, и в том же году в США был принят «Закон о чистоте пищевых продуктов и медикаментов» (так появилось ведомство FDA).$$),
  (243, $$«Хижина дяди Тома» Гарриет Бичер-Стоу (1852) обострила конфликт между Севером и Югом США. Когда Авраам Линкольн встретил писательницу в разгар Гражданской войны, он сказал: «Так это вы та маленькая женщина, которая написала книгу, развязавшую эту большую войну?».$$),
  (244, $$Публикация поэмы «Полтава» Пушкина заставила императора Николая I пересмотреть отношение к архивам петровской эпохи и открыть к ним доступ для историков.$$),
  (245, $$Детективы Эрла Стенли Гарднера о Перри Мейсоне популяризировали в США концепцию «права на адвоката» и презумпцию невиновности задолго до того, как Верховный суд США утвердил знаменитое «Правило Миранды» («Вы имеете право хранить молчание...»).$$),
  (246, $$Книга «Права человека» Томаса Пейна (1791) была запрещена в Англии, а автора судили за государственную измену, так как книга призывала к свержению монархии и защищала Французскую революцию.$$),
  (247, $$«Архипелаг ГУЛАГ» Александра Солженицына, тайно вывезенный на Запад и опубликованный в 1973 году, окончательно разрушил иллюзии западной левой интеллигенции относительно советской системы и ускорил идеологический крах СССР.$$),
  (248, $$Роман «Шум и ярость» Уильяма Фолкнера изменил структуру модернистской прозы, доказав издателям, что поток сознания и путаница во времени могут быть коммерчески успешными жанрами.$$),
  (249, $$После публикации книги «Безмолвная весна» Рэйчел Карсон (1962), рассказывающей об уничтожении птиц химикатами, в США была полностью запрещена продажа опасного пестицида ДДТ, и зародилось современное экологическое движение.$$),
  (250, $$«Судебный поединок» — после выхода исторического романа Вальтера Скотта «Айвенго» в Англии романтизировали средневековые традиции, однако это привело к тому, что юристы обнаружили брешь в законах: юридически судебные поединки не были отменены. Парламенту пришлось срочно принимать закон, запрещающий решать споры дракой.$$),
  (251, $$Слово «Пандемониум» (столица ада) было полностью выдумано поэтом Джоном Мильтоном для его эпической поэмы «Потерянный рай» (1667).$$),
  (252, $$Имя Ванесса выдумал писатель Джонатан Свифт. Он составил его из первых букв имени и фамилии своей близкой подруги Эстер Ванхомриг (Van-Ester).$$),
  (253, $$Слово «Сермяжная правда» вошло в обиход благодаря роману Ильи Ильфа и Евгения Петрова «Золотой теленок» (так выражался Васисуалий Лоханкин).$$),
  (254, $$Имя Оливия впервые зафиксировано в художественной литературе в пьесе Уильяма Шекспира «Двенадцатая ночь». До этого оно практически не встречалось.$$),
  (255, $$Слово «Гоблин» не является народным. В том виде и значении, в котором мы его знаем (зеленые злобные существа), его популяризировал Джордж Макдональд в сказке «Принцесса и гоблин» (1872), а затем развил Толкин.$$),
  (256, $$Название романа «Ночь нежна» Фицджеральд взял из поэмы Джона Китса «Ода соловью».$$),
  (257, $$Слово «Утопия» часто путают со словом «Дистопия» (Антиутопия). Термин «Дистопия» впервые публично использовал философ и экономист Джон Стюарт Милль в своей речи перед парламентом в 1868 году.$$),
  (258, $$Название повести «Старик и море» Хемингуэя изначально звучало как «Достоинство человека», но автор изменил его в последний момент, посчитав слишком пафосным.$$),
  (259, $$Слово «Сноб» изначально использовалось в Англии в списках студентов университетов (сокр. от лат. sine nobilitate — без благородства), чтобы отличать простолюдинов от аристократов. В литературу его ввел Уильям Теккерей в «Книге снобов».$$),
  (260, $$Имя Мелисса пришло из древнегреческой мифологии, но как популярное женское имя в Европе оно закрепилось после выхода поэмы Лудовико Ариосто «Неистовый Роланд» (1516).$$),
  (261, $$Лев Толстой обожал кататься на велосипеде. Он научился этому виду спорта в возрасте 67 лет. Московское общество пролетарских велосипедистов даже выдало ему именной билет.$$),
  (262, $$Иван Крылов был невероятным обжорой. О его гастрономических «подвигах» ходили легенды. Считается, что великий баснописец умер от заворота кишок после того, как съел критическое количество перепелов.$$),
  (263, $$Антон Чехов был страстным садоводом. На своей даче в Мелихове он лично высадил более сотни кустов роз, десятки деревьев и вывел особый сорт вишни.$$),
  (264, $$Михаил Салтыков-Щедрин занимал пост вице-губернатора Рязани и Твери. Он был настолько честным и жестким чиновником, что местные дворяне называли его «вице-робеспьером».$$),
  (265, $$Николай Гумилев был профессиональным исследователем Африки. Он совершил несколько опасных экспедиций в Абиссинию (Эфиопию), откуда привез уникальные этнографические коллекции для Кунсткамеры.$$),
  (266, $$Владимир Набоков открыл несколько новых видов бабочек (в основном семейства Голубянок). Набоков был профессиональным энтомологом, и его именем назван целый ряд видов этих насекомых.$$),
  (267, $$Александр Куприн успел сменить десятки профессий до того, как стать известным писателем: он был военным, цирковым борцом, зубным врачом, актером, воздухоплавателем и рыбаком.$$),
  (268, $$Максим Горький (Алексей Пешков) не получил даже среднего образования — он окончил лишь начальное училище. Все свои колоссальные знания он приобрел исключительно путем самообразования.$$),
  (269, $$Василий Жуковский был главным наставником и учителем Александра II. Именно Жуковский привил будущему императору гуманные взгляды, которые привели к отмене крепостного права.$$),
  (270, $$Александр Грибоедов предчувствовал свою гибель в Персии. Уезжая туда в качестве посла, он сказал своему другу: «Вы не знаете этих людей: увидите, что дело дойдет до ножей». Вскоре посольство было разгромлено фанатиками.$$),
  (271, $$Стивен Кинг долгие годы борется с трискайдекафобией — паническим страхом перед числом 13. Во время чтения книг он никогда не останавливается на 13-й или 26-й (13х2) страницах.$$),
  (272, $$Говард Филлипс Лавкрафт при жизни публиковался только в дешевых «бульварных» журналах (типа Weird Tales) и умер в полной нищете от рака, так и не узнав, что созданный им «Миф Ктулху» станет культовой вехой мировой культуры.$$),
  (273, $$Рэй Брэдбери панически боялся автомобилей и за всю свою долгую жизнь ни разу не сел за руль, предпочитая велосипед или общественный транспорт.$$),
  (274, $$Мэри Шелли хранила завернутое в шелк сердце своего покойного мужа, поэта Перси Биши Шелли, в ящике своего письменного стола вплоть до своей смерти.$$),
  (275, $$Клиффорд Саймак работал профессиональным журналистом более 40 лет и писал свою теплую философскую фантастику («Город», «Заповедник гоблинов») исключительно по выходным.$$),
  (276, $$Урсула Ле Гуин написала роман «Левая рука Тьмы» (1969), который стал первым крупным произведением в жанре андрогинной фантастики, где инопланетяне не имеют постоянного пола.$$),
  (277, $$Филип Дик продал права на экранизацию рассказа «Мы вам все припомним» (фильм «Вспомнить все» с Шварценеггером) всего за несколько тысяч долларов за пару месяцев до своей смерти.$$),
  (278, $$Дуглас Адамс придумал идею книги «Автостопом по галактике», когда лежал пьяным на поле в Инсбруке (Австрия), глядя на звездное небо с путеводителем по Европе в руках.$$),
  (279, $$Число 42 — ответ на «Главный вопрос жизни, вселенной и всего такого» в романе Адамса — было выбрано автором абсолютно случайно. Он просто хотел взять небольшое, ничем не примечательное число.$$),
  (280, $$Уильям Гибсон написал свой культовый роман «Нейромант», положивший начало жанру киберпанк, на старой механической печатной машинке 1927 года выпуска. На тот момент писатель вообще не разбирался в компьютерах.$$),
  (281, $$«Дьяволова Библия» (Гигантский кодекс, Codex Gigas) — рукопись начала XIII века, созданная в бенедиктинском монастыре в Чехии. Книга весит 75 кг, и, согласно легенде, монах написал ее за одну ночь с помощью самого дьявола, чей огромный портрет нарисован на одной из страниц.$$),
  (282, $$Рукопись Войнича — таинственная книга XV века, написанная на абсолютно неизвестном языке с использованием уникального алфавита. Ни один шифровальщик в мире (включая специалистов АНБ) до сих пор не смог ее расшифровать.$$),
  (283, $$«Книга судного дня» (Domesday Book) — первая всеобщая поземельная перепись в Англии, проведенная Вильгельмом Завоевателем в 1086 году. Название пошло от того, что данные переписи были окончательными и обжалованию не подлежали, как на Страшном суде.$$),
  (284, $$Палимпсест Архимеда — средневековая молитвенная книга, написанная поверх соскобленного текста византийского манускрипта X века. Ученые с помощью рентгена смогли прочесть нижний слой и обнаружили там утерянные трактаты Архимеда по математике.$$),
  (285, $$В древнем Риме свитки папируса хранились в специальных кожаных цилиндрах — капсах, к которым прикреплялись ярлыки с названием книги (титлусы), что является прообразом современных книжных корешков.$$),
  (286, $$Пергамент (материал для письма из кожи животных) получил свое название в честь города Пергам в Малой Азии, где его начали массово производить во II веке до н.э., когда Египет запретил экспорт папируса.$$),
  (287, $$Самый длинный свиток из сохранившихся древнеегипетских папирусов — Папирус Харриса (длина 41 метр). Он содержит списки пожертвований храмам от фараона Рамзеса III.$$),
  (288, $$«Книги-бабочки» — древнекитайский формат книг, где листы бумаги складывались пополам и склеивались по сгибу. При перелистывании страницы раскрывались как крылья бабочки.$$),
  (289, $$Свитки Мертвого моря (Кумранские рукописи) были случайно обнаружены пастухом-бедуином в 1947 году в пещерах, когда он искал потерявшуюся козу.$$),
  (290, $$Инкунабула переводится с латыни буквально как «в колыбели». Этот термин подчеркивает, что такие книги создавались в период младенчества книгопечатания.$$),
  (291, $$Джордж Мартин в молодости был организатором шахматных турниров. Доходы от шахмат позволяли ему тратить будние дни на написание своих первых фантастических рассказов.$$),
  (292, $$Стивен Кинг признался, что написал роман «Бегущий человек» всего за 72 часа под псевдонимом Ричард Бахман, работая в состоянии безумного писательского транса.$$),
  (293, $$Дж. К. Роулинг по требованию издателей скрыла свое полное имя (Джоан), использовав инициалы «Дж. К.», так как маркетологи боялись, что мальчики не захотят покупать фэнтези, написанное женщиной. Буква «К» (Кэтлин) взята в честь ее бабушки.$$),
  (294, $$Дэн Браун начинает свой рабочий день ровно в 4:00 утра. На его рабочем столе стоят старинные песочные часы, и каждые 60 минут он прерывается, чтобы сделать серию отжиманий и приседаний.$$),
  (295, $$Нил Гейман считает своим главным учителем Терри Пратчетта. Их совместный роман «Благие знамения» они писали, постоянно созваниваясь по телефону и зачитывая друг другу шутки.$$),
  (296, $$Джон Грин (автор «Виноваты звезды») перед тем как уйти в литературу, планировал стать епископальным священником и пять месяцев проработал капелланом в детской больнице. Этот опыт и лег в основу его главного бестселлера.$$),
  (297, $$Хуан Гомес-Хурадо (автор триллера «Красная королева») стал популярным благодаря тому, что выложил свою первую книгу в интернет бесплатно, попросив читателей перевести ему любую сумму, если книга понравится. Это принесло ему контракт с крупнейшим издательством.$$),
  (298, $$Сьюзен Коллинз при создании образа Китнисс Эвердин вдохновлялась древнегреческим мифом о Тесее и Минотавре, где Афины должны были посылать на съедение чудовищу семь юношей и семь девушек.$$),
  (299, $$Харуки Мураками до 29 лет не помышлял о литературе — он владел джазовым баром «Peter Cat» в Токио. Мысль написать роман пришла к нему внезапно во время бейсбольного матча, когда американский игрок Дэйв Хилтон выбил точный мяч.$$),
  (300, $$Томас Харрис написал «Молчание ягнят» на основе реального интервью с серийным убийцей Тедом Банди. А прототипом Ганнибала Лектера стал мексиканский тюремный врач-убийца Альфредо Балли Тревиньо, с которым писатель познакомился в тюрьме в 1960-х годах.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  CASE WHEN ordinal BETWEEN 251 AND 260 THEN 'PHILOLOGY' ELSE 'LITERATURE' END,
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;
